import { useEffect, useState } from 'react'
import { get, size } from 'lodash'
import { Container, CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../lang'
import PolicyDocumentCard from '../../../components/PolicyDocumentCard'
import { InsuranceDocumentStyle } from './index.style'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { useGetInsuranceDocs } from '../../../state/hooks/usePolicyState'
import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { withRouter } from 'react-router'

function InsuranceDocuments (props) {
  const [{ getInsuranceDocsData = {} }, getInsuranceDocsRequest] = useGetInsuranceDocs()
  const [
    {
      GET_INSURANCE_DOCS_ERROR, getInsuranceDocsStatus
    },
    dispatchError
  ] = useErrorContextValue()

  const [{
    GET_INSURANCE_DOCS_LOADER
  }, dispatchLoader
  ] = useLoaderContextValue()

  const { match } = props
  const [showBar, setShowBar] = useState(null)
  const [barMsg, setBarMsg] = useState('')

  useEffect(() => {
    if (GET_INSURANCE_DOCS_LOADER === undefined) {
      const policyId = get(match, 'params.policyId', '')
      getInsuranceDocsRequest({ policyId })
    }
  }, [getInsuranceDocsRequest, match,
    GET_INSURANCE_DOCS_LOADER
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_INSURANCE_DOCS_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_INSURANCE_DOCS_ERROR && getInsuranceDocsStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getInsuranceDocsStatus
      })
      dispatchError(resetError({
        getInsuranceDocsStatus: ''
      }))
    }
  }, [GET_INSURANCE_DOCS_ERROR, getInsuranceDocsStatus,
    dispatchError
  ])

  const handleShowSnackbar = (isShow, text) => {
    setShowBar(isShow)
    setBarMsg(text)
    setTimeout(() => {
      setShowBar(false)
    }, 4000)
  }

  const getTitle = (title, textAlign = 'left') => (
    <CustomText
      color={AgentColorPallette.fontDarkerGrey}
      bottom='0'
      weight={800}
      textAlign={textAlign}
      className='document-title'
    >
      {title}
    </CustomText>
  )

  return (
    <Container
      title={LANG_STRINGS.invoice}
      loader={GET_INSURANCE_DOCS_LOADER}
      displayBackButton
      hideBottomTabs
    >
      <InsuranceDocumentStyle>
        {getInsuranceDocsData?.total_doc_count === 0 && getTitle(LANG_STRINGS.documentsUnavailable, 'center')}

        {!!size(getInsuranceDocsData.invoice_polis) && getTitle(LANG_STRINGS.policyInvoice)}
        {
          !!size(getInsuranceDocsData.invoice_polis) && getInsuranceDocsData.invoice_polis.map((doc, index) => (
            <PolicyDocumentCard
              key={`invoice-documents-${index}`}
              type='link'
              name={doc.name}
              id={`invoice_${index + 1}`}
              size={doc.size}
              url={`/agent/invoice/${doc.id}/detail`}
              onShowSnackbar={handleShowSnackbar}
            />
          ))
        }
        {!!size(getInsuranceDocsData.invoice_endorsement) && getTitle(LANG_STRINGS.endorsementInvoice)}
        {
          !!size(getInsuranceDocsData.invoice_endorsement) && getInsuranceDocsData.invoice_endorsement.map((doc, index) => (
            <PolicyDocumentCard
              onShowSnackbar={handleShowSnackbar}
              type='link'
              key={`endorsement-documents-${index}`}
              id='endorsement_documents'
              name={doc.name}
              size={doc.size}
              url={`/agent/invoice/${doc.id}/detail`}
            />
          ))
        }
      </InsuranceDocumentStyle>
      {
        showBar && (<ShowSnackbar show={showBar} text={barMsg} />)
      }
    </Container>
  )
}

export default withRouter(InsuranceDocuments)
