import { withRouter } from 'react-router'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { downloadFile } from '../../../../../helpers/mitraUtils/mitra-utility'
import { DOCUMENT, DOWNLOAD_GOLD } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { PolicyDocumentCardStyle } from './index.style'

function PolicyDocumentCard (props) {
  const { name, size, url, onShowSnackbar, id, type } = props

  const handleDownload = () => {
    if (type === 'link') {
      props.history.push(url)
    } else {
      downloadFile(url, `${name}.pdf`)
      onShowSnackbar(true, `${name} ${LANG_STRINGS.downloadSuccessfully}`)
    }
  }

  return (
    <PolicyDocumentCardStyle
      justify='space-between'
      align='center'
      id={id}
      onClick={handleDownload}
    >
      <Row align='center'>
        <img src={DOCUMENT} alt='documents' width='20px' />
        <div className='document-name'>
          <CustomText color={AgentColorPallette.black}>
            {name}
          </CustomText>
          {
            size && (
              <CustomText color={AgentColorPallette.fontSemiGrey} size='10px'>
                {size}
              </CustomText>
            )
          }
        </div>
      </Row>
      {
        type === 'link'
          ? (
            <div className='up-down'>
              <i className='fas fa-angle-down right-caret' />
            </div>
          )
          : <img src={DOWNLOAD_GOLD} alt='Download' />
      }
    </PolicyDocumentCardStyle>
  )
}

export default withRouter(PolicyDocumentCard)
